/bin/bash -lc "python - <<'PY'
import urllib.request, re
for url in ['https://raw.githubusercontent.com/Kuanhao-Chao/OpenSpliceAI/main/README.md','https://ccb.jhu.edu/openspliceai/content/quick_start_guide/index.html','https://ccb.jhu.edu/openspliceai/content/openspliceai_predict.html','https://ccb.jhu.edu/openspliceai/content/pretrained_model.html','https://ccb.jhu.edu/openspliceai/content/installation.html']:
    print('\\nURL',url)
    try:
        txt=urllib.request.urlopen(url,timeout=20).read().decode('utf-8','replace')
        for pat in ['OSAI','MANE','10000','zenodo','model','download','checkpoint']:
            if pat.lower() in txt.lower(): print(' contains',pat)
        for m in re.finditer(r'https?://["'^'"\\s\"<>]+', txt):
            s=m.group(0)
            if any(x in s.lower() for x in ['model','zenodo','github','download','pth','pt','tar','zip','osai']): print(s[:300])
    except Exception as e: print('ERR',e)
PY"

