/bin/bash -lc "python - <<'PY'
import urllib.request, json
queries=['openspliceai','spliceai','pytorch']
for q in queries:
 print('\\nQUERY', q)
 url=f'https://quay.io/api/v1/find/repositories?query={q}'
 try:
  data=json.load(urllib.request.urlopen(url,timeout=20))
  for r in data.get('results',[])[:10]:
   print(r.get('namespace'), r.get('name'), r.get('description'))
 except Exception as e: print('ERR',e)
PY"

